sys_script_include.script:
var getEXCEL = Class.create();
getEXCEL.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    parseExcel: function() {
        var mrvs = [];
        var attid = this.getParameter('sysparm_attachment');
        var parser = new sn_impex.GlideExcelParser();
        var attachment = new GlideSysAttachment();
        var attachmentStream = attachment.getContentStream(attid);

        if (!attachmentStream) {
            gs.error("Failed to get attachment stream for: " + attid);
            return JSON.stringify([]);
        }

        parser.setSource(attachmentStream);
        var list_sheet_name = parser.getSheetNames();

        for (var i = 0; i < list_sheet_name.length; i++) {
            parser.setSheetName(list_sheet_name[i]);
            if (parser.parse()) {
                var headers = parser.getColumnHeaders();
                // 确保列头存在
                if (headers.length < 2) continue;

                var header1 = headers[0];
                var header2 = headers[1];

                while (parser.next()) {
                    var row = parser.getRow();
                    // 跳过空行
                    if (!row[header1] && !row[header2]) continue;

                    mrvs.push({
                        'sn': row[header1] || '',
                        'name': row[header2] || ''
                    });
                }
            }
        }
        return JSON.stringify(mrvs);
    },
    type: 'getEXCEL'
});
